function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function call(path, options = {}) {
  const response = await fetch(apiOrigin() + path, { headers: { Accept: 'application/json', 'Content-Type': 'application/json' }, ...options })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}

async function preflight(strategyId, input) {
  const strategy = await call('/api/strategies/' + encodeURIComponent(strategyId))
  if (strategy.implementation === 'python') {
    if (!strategy.python_source_sha256) throw new Error('Python strategy source is missing or has no hash')
    if (input.confirm_python_execution !== true) throw new Error('Python research execution requires source review, an explicit user request, and confirm_python_execution=true')
  }
  return { strategy_type: strategy.strategy_type, implementation: strategy.implementation, python_source_sha256: strategy.python_source_sha256 || null }
}

async function run(input) {
  const base = '/api/research/runs'
  if (input.operation === 'list') return call(base + '?limit=' + Math.max(1, Math.min(200, Number(input.limit || 20))))
  if (input.operation === 'get') {
    const id = String(input.run_id || '').trim()
    if (!id) throw new Error('run_id is required for get')
    return call(base + '/' + encodeURIComponent(id))
  }
  if (input.operation === 'start') {
    if (input.confirm_research_run !== true) throw new Error('Starting full research requires an explicit user request and confirm_research_run=true')
    const strategyId = String(input.strategy_id || '').trim()
    if (!strategyId || !input.start_date || !input.end_date) throw new Error('strategy_id, start_date, and end_date are required for start')
    const strategyPreflight = await preflight(strategyId, input)
    const payload = await call(base, { method: 'POST', body: JSON.stringify({ strategy_id: strategyId, profile: input.profile === 'runtime' ? 'runtime' : 'demo', start_date: String(input.start_date), end_date: String(input.end_date), account_id: String(input.account_id || 'paper') }) })
    return { ...payload, strategy_preflight: strategyPreflight }
  }
  const id = String(input.run_id || '').trim()
  if (!id) throw new Error('run_id is required')
  if (input.operation === 'cancel') {
    if (input.confirm_cancel !== true) throw new Error('Cancelling a research run requires an explicit user request and confirm_cancel=true')
    return call(base + '/' + encodeURIComponent(id) + '/cancel', { method: 'POST', body: '{}' })
  }
  if (input.operation === 'retry') {
    if (input.confirm_research_run !== true) throw new Error('Retrying full research requires an explicit user request and confirm_research_run=true')
    const previous = await call(base + '/' + encodeURIComponent(id))
    const strategyPreflight = await preflight(String(previous.strategy_id || ''), input)
    const payload = await call(base + '/' + encodeURIComponent(id) + '/retry', { method: 'POST', body: '{}' })
    return { ...payload, strategy_preflight: strategyPreflight }
  }
  throw new Error('Unsupported research run operation')
}
